     1→/**
     2→ * VTThought First-Run Setup Flow (ADR-017)
     3→ *
     4→ * Implements the 3-click onboarding experience for new users.
     5→ * Gets users from install to first transcription in under 60 seconds.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→import { TokenManager } from './tokenManager';
    10→
    11→/**
    12→ * Setup state machine states
    13→ */
    14→type SetupState =
    15→    | 'not_started'
    16→    | 'welcome'
    17→    | 'backend_url'
    18→    | 'token'
    19→    | 'microphone'
    20→    | 'testing'
    21→    | 'complete'
    22→    | 'error';
    23→
    24→/**
    25→ * Setup flow configuration
    26→ */
    27→interface SetupConfig {
    28→    backendUrl: string;
    29→    token: string;
    30→    microphoneGranted: boolean;
    31→}
    32→
    33→/**
    34→ * Quick pick action types
    35→ */
    36→interface QuickPickAction {
    37→    label: string;
    38→    description: string;
    39→    action: string;
    40→}
    41→
    42→/**
    43→ * First-run setup flow manager
    44→ *
    45→ * Implements ADR-017: Frictionless onboarding with:
    46→ * 1. Welcome screen with Get Started option
    47→ * 2. Backend URL configuration
    48→ * 3. Token acquisition from backend
    49→ * 4. Microphone permission request
    50→ * 5. Connection testing
    51→ * 6. Completion celebration
    52→ */
    53→export class SetupFlow {
    54→    private state: SetupState = 'not_started';
    55→    private config: SetupConfig = {
    56→        backendUrl: '',
    57→        token: '',
    58→        microphoneGranted: false
    59→    };
    60→
    61→    private static readonly SETUP_COMPLETE_KEY = 'vtthought.setupComplete';
    62→    private static readonly FIRST_TRANSCRIPTION_KEY = 'vtthought.firstTranscription';
    63→
    64→    constructor(
    65→        private readonly context: vscode.ExtensionContext,
    66→        private readonly tokenManager: TokenManager
    67→    ) {}
    68→
    69→    /**
    70→     * Check if this is a first-run scenario
    71→     */
    72→    public async isFirstRun(): Promise<boolean> {
    73→        const setupComplete = this.context.globalState.get<boolean>(
    74→            SetupFlow.SETUP_COMPLETE_KEY,
    75→            false
    76→        );
    77→        return !setupComplete;
    78→    }
    79→
    80→    /**
    81→     * Start the first-run setup flow
    82→     */
    83→    public async start(): Promise<void> {
    84→        this.state = 'welcome';
    85→
    86→        // Show welcome screen
    87→        await this.showWelcome();
    88→    }
    89→
    90→    /**
    91→     * Show welcome quick pick
    92→     */
    93→    private async showWelcome(): Promise<void> {
    94→        const items: QuickPickAction[] = [
    95→            {
    96→                label: '$(rocket) Get Started',
    97→                description: 'Set up in 30 seconds',
    98→                action: 'start'
    99→            },
   100→            {
   101→                label: '$(book) Learn More',
   102→                description: 'Open documentation',
   103→                action: 'docs'
   104→            }
   105→        ];
   106→
   107→        const choice = await vscode.window.showQuickPick(items, {
   108→            placeHolder: 'Welcome to VTThought Voice Code!',
   109→            title: 'VTThought Setup'
   110→        });
   111→
   112→        if (!choice) {
   113→            // User dismissed the dialog
   114→            this.state = 'not_started';
   115→            return;
   116→        }
   117→
   118→        switch (choice.action) {
   119→            case 'start':
   120→                await this.startQuickSetup();
   121→                break;
   122→            case 'docs':
   123→                await vscode.env.openExternal(
   124→                    vscode.Uri.parse('https://github.com/jedarden/vtthought')
   125→                );
   126→                // Re-show welcome after opening docs
   127→                await this.showWelcome();
   128→                break;
   129→        }
   130→    }
   131→
   132→    /**
   133→     * Run the quick setup flow
   134→     */
   135→    private async startQuickSetup(): Promise<void> {
   136→        // Step 1: Backend URL
   137→        this.state = 'backend_url';
   138→        const backendUrl = await this.promptBackendUrl();
   139→        if (!backendUrl) {
   140→            this.state = 'not_started';
   141→            return;
   142→        }
   143→        this.config.backendUrl = backendUrl;
   144→
   145→        // Step 2: Validate backend and get token
   146→        this.state = 'token';
   147→        const token = await this.promptAndValidateToken(backendUrl);
   148→        if (!token) {
   149→            this.state = 'not_started';
   150→            return;
   151→        }
   152→        this.config.token = token;
   153→
   154→        // Step 3: Microphone permission
   155→        this.state = 'microphone';
   156→        const micGranted = await this.requestMicrophonePermission();
   157→        if (!micGranted) {
   158→            this.state = 'not_started';
   159→            return;
   160→        }
   161→        this.config.microphoneGranted = true;
   162→
   163→        // Step 4: Test connection (optional but recommended)
   164→        this.state = 'testing';
   165→        const testResult = await this.testConnection(backendUrl, token);
   166→        if (!testResult && !await this.skipTest()) {
   167→            this.state = 'not_started';
   168→            return;
   169→        }
   170→
   171→        // Step 5: Complete setup
   172→        await this.completeSetup();
   173→    }
   174→
   175→    /**
   176→     * Prompt for backend URL
   177→     */
   178→    private async promptBackendUrl(): Promise<string | null> {
   179→        const url = await vscode.window.showInputBox({
   180→            prompt: 'Enter your VTThought backend URL',
   181→            placeHolder: 'http://localhost:8000',
   182→            value: 'http://localhost:8000',
   183→            validateInput: (value) => {
   184→                try {
   185→                    const parsed = new URL(value);
   186→                    if (!['http:', 'https:'].includes(parsed.protocol)) {
   187→                        return 'URL must use http or https';
   188→                    }
   189→                    return null;
   190→                } catch {
   191→                    return 'Please enter a valid URL';
   192→                }
   193→            }
   194→        });
   195→
   196→        if (!url) {
   197→            return null;
   198→        }
   199→
   200→        // Normalize URL (remove trailing slash)
   201→        return url.replace(/\/$/, '');
   202→    }
   203→
   204→    /**
   205→     * Validate backend and prompt for token
   206→     */
   207→    private async promptAndValidateToken(backendUrl: string): Promise<string | null> {
   208→        // First, validate backend is reachable
   209→        const reachable = await this.validateBackend(backendUrl);
   210→        if (!reachable) {
   211→            return null;
   212→        }
   213→
   214→        // Check if backend is in single-user mode
   215→        const singleUserMode = await this.checkSingleUserMode(backendUrl);
   216→        if (singleUserMode) {
   217→            // No token needed
   218→            return 'single_user_mode';
   219→        }
   220→
   221→        // Prompt user to get token from backend
