   569→    /**
   570→     * Connect to backend WebSocket
   571→     */
   572→    private async connectBackend(): Promise<void> {
   573→        // Check authentication first (ADR-002)
   574→        if (!this.state.isAuthenticated) {
   575→            const result = await vscode.window.showWarningMessage(
   576→                'VTThought is not configured. Would you like to set up authentication?',
   577→                'Setup',
   578→                'Cancel'
   579→            );
   580→
   581→            if (result === 'Setup') {
   582→                await this.setupAuthentication();
   583→                if (!this.state.isAuthenticated) {
   584→                    this.log('Connection cancelled: Authentication not configured');
   585→                    return;
   586→                }
   587→            } else {
   588→                this.log('Connection cancelled: Authentication not configured');
   589→                return;
   590→            }
   591→        }
   592→
   593→        const apiUrl = await this.tokenManager.getBackendUrl();
   594→        const wsUrl = await this.tokenManager.getWebSocketUrl();
   595→
   596→        this.log(`Connecting to backend: ${apiUrl}`);
   597→
   598→        try {
   599→            // First, verify backend is reachable via health check
   600→            const authHeader = await this.tokenManager.getAuthHeader();
   601→            const headers: Record<string, string> = {};
   602→            if (authHeader) {
   603→                headers['Authorization'] = authHeader;
   604→            }
   605→
   606→            const response = await fetch(`${apiUrl}/api/health`, { headers });
   607→
   608→            if (!response.ok) {
   609→                if (response.status === 401) {
   610→                    // Token expired or invalid
   611→                    await this.tokenManager.clearToken();
   612→                    this.state.isAuthenticated = false;
   613→                    vscode.window.showErrorMessage(
   614→                        'VTThought: Authentication failed. Please set up authentication again.',
   615→                        'Setup'
   616→                    ).then(action => {
   617→                        if (action === 'Setup') {
   618→                            vscode.commands.executeCommand('vtthought.setupAuthentication');
   619→                        }
   620→                    });
   621→                    return;
   622→                }
   623→                throw new Error(`Health check failed: ${response.status}`);
   624→            }
   625→
   626→            // Establish WebSocket connection
   627→            this.audioStreamer = new AudioStreamer(wsUrl, { sampleRate: 16000, channels: 1 }, {
   628→                onConnected: () => {
   629→                    this.state.isConnected = true;
   630→                    this.updateStatusDisplay();
   631→                    this.log('WebSocket connected successfully');
   632→                },
   633→                onDisconnected: () => {
   634→                    this.state.isConnected = false;
   635→                    this.state.isRecording = false;
   636→                    this.updateStatusDisplay();
   637→                    this.log('WebSocket disconnected');
   638→                },
   639→                onError: (error) => {
   640→                    this.log(`WebSocket error: ${error.message}`);
   641→                    vscode.window.showErrorMessage(`VTThought: WebSocket error - ${error.message}`);
   642→                },
   643→                onMessage: async (message) => {
   644→                    // Handle server messages (interim, streaming, final, error)
   645→                    if (this.dictationHandler) {
   646→                        await this.dictationHandler.handleMessage(message);
   647→                    }
   648→                }
   649→            });
   650→
   651→            await this.audioStreamer.connect();
   652→
   653→            this.log('Connected to backend successfully');
   654→            vscode.window.showInformationMessage('VTThought: Connected to backend');
   655→
   656→        } catch (error) {
   657→            this.log(`Connection failed: ${error}`);
   658→            vscode.window.showErrorMessage(
   659→                `VTThought: Failed to connect to backend at ${apiUrl}. Ensure the backend is running and try again.`
   660→            );
   661→            this.state.isConnected = false;
   662→            this.updateStatusDisplay();
   663→        }
   664→    }
   665→
   666→    /**
   667→     * Disconnect from backend
   668→     */
   669→    private disconnect(): void {
   670→        // Stop recording if active
   671→        if (this.state.isRecording) {
   672→            this.stopRecording();
   673→        }
   674→
   675→        // Close WebSocket connection
   676→        if (this.audioStreamer) {
   677→            this.audioStreamer.close();
   678→            this.audioStreamer = null;
   679→        }
   680→
   681→        this.state.isConnected = false;
   682→        this.state.isRecording = false;
   683→        this.updateStatusDisplay();
   684→
   685→        this.log('Disconnected from backend');
   686→        vscode.window.showInformationMessage('VTThought: Disconnected from backend');
   687→    }
