   705→        if (this.state.isConnected) {
   706→            this.connectionStatusBarItem.text = '$radio-tower VTThought: Connected';
   707→            this.connectionStatusBarItem.tooltip = 'Connected to backend';
   708→            this.connectionStatusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.prominentBackground');
   709→        } else {
   710→            this.connectionStatusBarItem.text = '$circle-large-outline VTThought: Disconnected';
   711→            this.connectionStatusBarItem.tooltip = 'Click to connect to backend';
   712→            this.connectionStatusBarItem.backgroundColor = undefined;
