     1→/**
     2→ * VTThought Token Manager (ADR-002)
     3→ *
     4→ * Manages authentication tokens for the VTThought extension.
     5→ * Uses VS Code's secret storage for secure token persistence.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→
    10→/**
    11→ * Token Manager for VTThought extension authentication.
    12→ *
    13→ * Handles:
    14→ * - Secure storage of extension tokens using VS Code's secret storage
    15→ * - Backend URL configuration
    16→ * - Token validation and refresh
    17→ */
    18→export class TokenManager {
    19→    private static readonly TOKEN_KEY = 'vtthought.token';
    20→    private static readonly BACKEND_URL_KEY = 'vtthought.backendUrl';
    21→
    22→    private constructor(private readonly context: vscode.ExtensionContext) {}
    23→
    24→    /**
    25→     * Create a TokenManager instance.
    26→     *
    27→     * @param context - VS Code extension context
    28→     * @returns TokenManager instance
    29→     */
    30→    public static create(context: vscode.ExtensionContext): TokenManager {
    31→        return new TokenManager(context);
    32→    }
    33→
    34→    /**
    35→     * Store the extension token in secure storage.
    36→     *
    37→     * @param token - The extension token to store
    38→     */
    39→    public async storeToken(token: string): Promise<void> {
    40→        await this.context.secrets.store(TokenManager.TOKEN_KEY, token);
    41→    }
    42→
    43→    /**
    44→     * Get the stored extension token.
    45→     *
    46→     * @returns The stored token or undefined if not found
    47→     */
    48→    public async getToken(): Promise<string | undefined> {
    49→        return await this.context.secrets.get(TokenManager.TOKEN_KEY);
    50→    }
    51→
    52→    /**
    53→     * Clear the stored extension token.
    54→     */
    55→    public async clearToken(): Promise<void> {
    56→        await this.context.secrets.delete(TokenManager.TOKEN_KEY);
    57→    }
    58→
    59→    /**
    60→     * Check if a token is stored.
    61→     *
    62→     * @returns True if a token is stored
    63→     */
    64→    public async hasToken(): Promise<boolean> {
    65→        const token = await this.getToken();
    66→        return token !== undefined;
    67→    }
    68→
    69→    /**
    70→     * Store the backend URL.
    71→     *
    72→     * @param url - The backend URL to store
    73→     */
    74→    public async storeBackendUrl(url: string): Promise<void> {
    75→        await this.context.globalState.update(TokenManager.BACKEND_URL_KEY, url);
    76→    }
    77→
    78→    /**
    79→     * Get the stored backend URL.
    80→     *
    81→     * @returns The stored backend URL or default
    82→     */
    83→    public async getBackendUrl(): Promise<string> {
    84→        // Check global state first
    85→        const storedUrl = this.context.globalState.get<string>(TokenManager.BACKEND_URL_KEY);
    86→        if (storedUrl) {
    87→            return storedUrl;
    88→        }
    89→
    90→        // Fall back to configuration
    91→        const config = vscode.workspace.getConfiguration('vtthought');
    92→        return config.get<string>('backendUrl', 'http://localhost:8000');
    93→    }
    94→
    95→    /**
    96→     * Get the WebSocket URL for audio streaming.
    97→     *
    98→     * @returns The WebSocket URL with token parameter
    99→     */
   100→    public async getWebSocketUrl(): Promise<string> {
   101→        const backendUrl = await this.getBackendUrl();
   102→        const token = await this.getToken();
   103→
   104→        if (!token) {
   105→            throw new Error('No authentication token stored');
   106→        }
   107→
   108→        // Convert HTTP to WebSocket protocol
   109→        const wsUrl = backendUrl
   110→            .replace(/^https:\/\//, 'wss://')
   111→            .replace(/^http:\/\//, 'ws://');
   112→
   113→        // Append token as query parameter
   114→        return `${wsUrl}/api/ws/audio?token=${encodeURIComponent(token)}`;
   115→    }
   116→
   117→    /**
   118→     * Validate that authentication is configured.
   119→     *
   120→     * @returns True if both token and backend URL are configured
   121→     */
   122→    public async isConfigured(): Promise<boolean> {
   123→        const token = await this.getToken();
   124→        const backendUrl = await this.getBackendUrl();
   125→        return !!token && !!backendUrl;
   126→    }
   127→
   128→    /**
   129→     * Get authorization header for HTTP requests.
   130→     *
   131→     * @returns Authorization header value or undefined
   132→     */
   133→    public async getAuthHeader(): Promise<string | undefined> {
   134→        const token = await this.getToken();
   135→        if (!token) {
   136→            return undefined;
   137→        }
   138→        return `Bearer ${token}`;
   139→    }
   140→
   141→    /**
   142→     * Clear all stored authentication data.
   143→     */
   144→    public async clearAll(): Promise<void> {
   145→        await this.clearToken();
   146→        await this.context.globalState.update(TokenManager.BACKEND_URL_KEY, undefined);
   147→    }
   148→}
   149→
   150→/**
   151→ * Authentication status for the extension.
   152→ */
   153→export interface AuthStatus {
   154→    isConfigured: boolean;
   155→    hasToken: boolean;
   156→    backendUrl: string;
   157→}
   158→
   159→/**
   160→ * Get the current authentication status.
   161→ *
   162→ * @param tokenManager - The TokenManager instance
   163→ * @returns Current authentication status
   164→ */
   165→export async function getAuthStatus(tokenManager: TokenManager): Promise<AuthStatus> {
   166→    const [hasToken, backendUrl] = await Promise.all([
   167→        tokenManager.hasToken(),
   168→        tokenManager.getBackendUrl(),
   169→    ]);
   170→
   171→    return {
   172→        isConfigured: hasToken && !!backendUrl,
   173→        hasToken,
   174→        backendUrl,
   175→    };
   176→}
