     1→/**
     2→ * VTThought Text Insertion (ADR-007)
     3→ *
     4→ * Manages text insertion into VS Code editor and terminal.
     5→ * Implements interim text display with atomic rewriting.
     6→ */
     7→
     8→import * as vscode from 'vscode';
     9→import { SetupFlow } from './setupFlow';
    10→
    11→/**
    12→ * Server message types from backend WebSocket.
    13→ */
    14→export type ServerMessage =
    15→    | { type: 'interim'; text: string; is_final: boolean; confidence: number; changes: TextChange[] }  // eslint-disable-line @typescript-eslint/naming-convention
    16→    | { type: 'streaming'; token: string; position: number }
    17→    | { type: 'final'; raw: string; cleaned: string; commands: VoiceCommand[] }
    18→    | { type: 'error'; code: string; message: string };
    19→
    20→/**
    21→ * Text edit operation for interim updates.
    22→ */
    23→export interface TextChange {
    24→    start: number;
    25→    deleteCount: number;
    26→    insert: string;
    27→}
    28→
    29→/**
    30→ * Voice command to execute.
    31→ */
    32→export interface VoiceCommand {
    33→    action: string;
    34→    params?: Record<string, unknown>;
    35→    terminal?: boolean;
    36→}
    37→
    38→/**
    39→ * Manages interim text display with rewriting support.
    40→ *
    41→ * Key concepts:
    42→ * - anchor: Fixed position where dictation started (never moves)
    43→ * - interimLength: Current length of interim text (for calculating replacement range)
    44→ * - Atomic replacement: Uses editBuilder.replace() for flicker-free updates
    45→ * - Undo grouping: All interim edits are one undo operation
    46→ *
    47→ * Implements the interim text manager from ADR-007.
    48→ */
    49→export class InterimTextManager {
    50→    // Fixed starting point - never moves during dictation
    51→    private anchor: vscode.Position | null = null;
    52→
    53→    // Current interim text length for calculating replacement range
    54→    private interimLength = 0;
    55→
    56→    // Decoration for gray/italic interim styling
    57→    private readonly interimStyle: vscode.TextEditorDecorationType;
    58→
    59→    constructor() {
    60→        this.interimStyle = vscode.window.createTextEditorDecorationType({
    61→            color: new vscode.ThemeColor('editorGhostText.foreground'),
    62→            fontStyle: 'italic',
    63→            // Optional: add subtle background
    64→            backgroundColor: new vscode.ThemeColor('editor.wordHighlightBackground'),
    65→        });
    66→    }
    67→
    68→    /**
    69→     * Handle an interim result from the server.
    70→     * Replaces all existing interim text with new text.
    71→     */
    72→    async handleInterim(
    73→        editor: vscode.TextEditor,
    74→        text: string,
    75→        isFinal: boolean
    76→    ): Promise<void> {
    77→        // First interim: record anchor position
    78→        if (!this.anchor) {
    79→            this.anchor = editor.selection.active;
    80→        }
    81→
    82→        // Calculate the range of existing interim text
    83→        const interimStart = this.anchor;
    84→        const interimEnd = this.anchor.translate(0, this.interimLength);
    85→        const interimRange = new vscode.Range(interimStart, interimEnd);
    86→
    87→        // Atomic edit: replace entire interim region with new text
    88→        const success = await editor.edit(editBuilder => {
    89→            if (this.interimLength > 0) {
    90→                // Replace existing interim text
    91→                editBuilder.replace(interimRange, text);
    92→            } else {
    93→                // First insertion
    94→                editBuilder.insert(this.anchor!, text);
    95→            }
    96→        }, {
    97→            // Undo grouping: don't create undo stops between interim edits
    98→            undoStopBefore: false,
    99→            undoStopAfter: false,
   100→        });
   101→
   102→        if (!success) {
   103→            console.warn('InterimTextManager: edit failed');
   104→            return;
   105→        }
   106→
   107→        // Update tracked length
   108→        this.interimLength = text.length;
   109→
   110→        // Apply or remove interim styling
   111→        if (!isFinal) {
   112→            const newRange = new vscode.Range(
   113→                this.anchor,
   114→                this.anchor.translate(0, this.interimLength)
   115→            );
   116→            editor.setDecorations(this.interimStyle, [newRange]);
   117→        } else {
   118→            // Final STT result: remove interim styling
   119→            editor.setDecorations(this.interimStyle, []);
   120→        }
   121→
   122→        // Move cursor to end of inserted text
   123→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   124→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   125→    }
   126→
   127→    /**
   128→     * Handle streaming LLM cleanup tokens.
   129→     * First token replaces interim text; subsequent tokens append.
   130→     */
   131→    async handleStreamingToken(
   132→        editor: vscode.TextEditor,
   133→        token: string,
   134→        position: number  // Character position in the cleaned output
   135→    ): Promise<void> {
   136→        if (!this.anchor) {
   137→            return;
   138→        }
   139→
   140→        // Clear interim styling on first token
   141→        if (position === 0) {
   142→            editor.setDecorations(this.interimStyle, []);
   143→        }
   144→
   145→        if (position === 0 && this.interimLength > 0) {
   146→            // First token: replace entire interim text
   147→            const interimRange = new vscode.Range(
   148→                this.anchor,
   149→                this.anchor.translate(0, this.interimLength)
   150→            );
   151→            await editor.edit(eb => eb.replace(interimRange, token), {
   152→                undoStopBefore: false,
   153→                undoStopAfter: false,
   154→            });
   155→            this.interimLength = token.length;
   156→        } else {
   157→            // Subsequent tokens: append
   158→            const insertPos = this.anchor.translate(0, this.interimLength);
   159→            await editor.edit(eb => eb.insert(insertPos, token), {
   160→                undoStopBefore: false,
   161→                undoStopAfter: false,
   162→            });
   163→            this.interimLength += token.length;
   164→        }
   165→
   166→        // Move cursor to end
   167→        const newCursorPos = this.anchor.translate(0, this.interimLength);
   168→        editor.selection = new vscode.Selection(newCursorPos, newCursorPos);
   169→    }
   170→
   171→    /**
   172→     * Finalize the dictation session.
   173→     * Creates undo stop so entire dictation is one undo operation.
   174→     */
   175→    async finalize(editor: vscode.TextEditor): Promise<void> {
   176→        if (!this.anchor) {
   177→            return;
   178→        }
   179→
   180→        // Create final undo stop - entire dictation is now one undo
   181→        await editor.edit(() => {}, {
   182→            undoStopBefore: false,
   183→            undoStopAfter: true,  // End the undo group
   184→        });
   185→
   186→        // Clear styling
   187→        editor.setDecorations(this.interimStyle, []);
   188→
   189→        // Reset state
   190→        this.reset();
   191→    }
   192→
   193→    /**
   194→     * Cancel dictation and remove any interim text.
   195→     */
   196→    async cancel(editor: vscode.TextEditor): Promise<void> {
   197→        if (!this.anchor || this.interimLength === 0) {
   198→            this.reset();
   199→            return;
   200→        }
   201→
   202→        // Delete the interim text
   203→        const interimRange = new vscode.Range(
   204→            this.anchor,
   205→            this.anchor.translate(0, this.interimLength)
   206→        );
   207→        await editor.edit(eb => eb.delete(interimRange));
   208→
   209→        // Clear styling and reset
   210→        editor.setDecorations(this.interimStyle, []);
   211→        this.reset();
   212→    }
   213→
   214→    reset(): void {
   215→        this.anchor = null;
   216→        this.interimLength = 0;
   217→    }
   218→
   219→    isActive(): boolean {
   220→        return this.anchor !== null;
   221→    }
   222→
   223→    dispose(): void {
   224→        this.interimStyle.dispose();
   225→    }
   226→}
   227→
   228→/**
   229→ * Handles text insertion into terminal.
   230→ */
   231→export class TerminalInserter {
   232→    /**
   233→     * Terminals receive only final cleaned tokens - no interim display.
   234→     * Interim results are ignored since terminal text can't be "replaced".
   235→     */
   236→    handleMessage(terminal: vscode.Terminal, msg: ServerMessage): void {
   237→        switch (msg.type) {
   238→            case 'interim':
   239→                // Ignore - terminals can't replace text
   240→                break;
   241→
   242→            case 'streaming':
   243→                // Stream each cleaned token directly
   244→                terminal.sendText(msg.token, false);
   245→                break;
   246→
   247→            case 'final':
   248→                // Execute voice commands
   249→                for (const cmd of msg.commands) {
   250→                    this.executeCommand(terminal, cmd);
   251→                }
   252→                break;
   253→        }
   254→    }
   255→
   256→    private executeCommand(terminal: vscode.Terminal, cmd: VoiceCommand): void {
   257→        switch (cmd.action) {
   258→            case 'enter':
   259→                terminal.sendText('', true);  // Send newline
   260→                break;
   261→            case 'tab':
   262→                terminal.sendText('\t', false);
   263→                break;
   264→            case 'clear':
   265→                terminal.sendText('\u0015', false);  // Ctrl+U
   266→                break;
   267→            case 'cancel':
   268→                terminal.sendText('\x03', false);  // Ctrl+C
   269→                break;
   270→        }
   271→    }
   272→}
   273→
   274→/**
   275→ * Complete dictation handler for both editor and terminal.
   276→ */
   277→export class DictationHandler {
   278→    private readonly editorManager = new InterimTextManager();
   279→    private readonly terminalInserter = new TerminalInserter();
   280→
   281→    private currentFocus: 'editor' | 'terminal' | 'other' = 'other';
   282→    private context?: vscode.ExtensionContext;
   283→
   284→    constructor(context?: vscode.ExtensionContext) {
   285→        this.context = context;
   286→        this.trackFocus();
   287→    }
   288→
   289→    /**
   290→     * Set the extension context for first transcription celebration
   291→     */
   292→    public setContext(context: vscode.ExtensionContext): void {
   293→        this.context = context;
   294→    }
   295→
   296→    /**
   297→     * Track focus state between editor and terminal.
   298→     */
   299→    private trackFocus(): void {
   300→        vscode.window.onDidChangeActiveTextEditor(() => {
   301→            this.currentFocus = 'editor';
   302→        });
   303→
   304→        vscode.window.onDidChangeActiveTerminal(() => {
   305→            this.currentFocus = 'terminal';
   306→        });
   307→
   308→        vscode.window.onDidChangeWindowState((state) => {
   309→            if (!state.focused) {
   310→                this.currentFocus = 'other';
   311→            }
   312→        });
   313→    }
   314→
   315→    /**
   316→     * Handle server message and route to appropriate target.
   317→     */
   318→    async handleMessage(msg: ServerMessage): Promise<void> {
   319→        // Determine target based on focus
   320→        if (this.isTerminalFocused()) {
   321→            const terminal = vscode.window.activeTerminal;
   322→            if (terminal) {
   323→                this.terminalInserter.handleMessage(terminal, msg);
   324→            }
   325→            return;
   326→        }
   327→
   328→        const editor = vscode.window.activeTextEditor;
   329→        if (!editor) {
   330→            vscode.window.showWarningMessage('No active editor for dictation');
   331→            return;
   332→        }
   333→
   334→        switch (msg.type) {
   335→            case 'interim':
   336→                await this.editorManager.handleInterim(
   337→                    editor,
   338→                    msg.text,
   339→                    msg.is_final
   340→                );
   341→                break;
   342→
   343→            case 'streaming':
   344→                await this.editorManager.handleStreamingToken(
   345→                    editor,
   346→                    msg.token,
   347→                    msg.position
   348→                );
   349→                break;
   350→
   351→            case 'final':
   352→                await this.editorManager.finalize(editor);
   353→
   354→                // First transcription celebration (ADR-017)
   355→                if (this.context && msg.cleaned && msg.cleaned.length > 0) {
   356→                    await SetupFlow.onFirstTranscription(this.context, msg.cleaned);
   357→                }
   358→
   359→                // Execute voice commands after finalization
   360→                for (const cmd of msg.commands) {
   361→                    await this.executeVoiceCommand(cmd);
   362→                }
   363→                break;
   364→
   365→            case 'error':
   366→                await this.editorManager.cancel(editor);
   367→                vscode.window.showErrorMessage(`Dictation error: ${msg.message}`);
   368→                break;
   369→        }
   370→    }
   371→
   372→    private isTerminalFocused(): boolean {
   373→        // VS Code doesn't expose this directly; we track via events
   374→        return this.currentFocus === 'terminal';
   375→    }
   376→
   377→    private async executeVoiceCommand(cmd: VoiceCommand): Promise<void> {
   378→        if (cmd.terminal) {
   379→            const terminal = vscode.window.activeTerminal;
   380→            if (!terminal) {
   381→                return;
   382→            }
   383→
   384→            switch (cmd.action) {
   385→                case 'enter':
   386→                    terminal.sendText('', true);
   387→                    break;
   388→                case 'cancel':
   389→                    terminal.sendText('\x03', false);
   390→                    break;
   391→            }
   392→        } else {
   393→            // VS Code command
   394→            await vscode.commands.executeCommand(cmd.action, cmd.params);
   395→        }
   396→    }
   397→
   398→    dispose(): void {
   399→        this.editorManager.dispose();
   400→    }
   401→}
   402→

