   102→    /**
   103→     * Activate the extension
   104→     */
   105→    public async activate(): Promise<void> {
   106→        this.log('VTThought Extension Activated');
   107→
   108→        // Check for first-run setup (ADR-017)
   109→        const setupFlow = new SetupFlow(this.context, this.tokenManager);
   110→        const isFirstRun = await setupFlow.isFirstRun();
   111→
   112→        if (isFirstRun) {
   113→            this.log('First run detected - starting setup flow...');
   114→            // Show welcome after a short delay to let VS Code fully load
   115→            setTimeout(() => {
   116→                setupFlow.start().catch(err => {
