   122→            const authStatus = await getAuthStatus(this.tokenManager);
   123→            this.state.isAuthenticated = authStatus.isConfigured;
   124→            this.state.backendUrl = authStatus.backendUrl;
   125→
   126→            if (!authStatus.isConfigured) {
   127→                this.log('Authentication not configured. Run "VTThought: Setup Authentication" to configure.');
   128→            }
   129→
   130→            // Auto-connect if enabled and authenticated
   131→            const config = vscode.workspace.getConfiguration('vtthought');
