   254→    /**
   255→     * Analyze a transcription for voice commands
   256→     */
   257→    private async analyzeVoiceCommand(): Promise<void> {
   258→        const input = await vscode.window.showInputBox({
   259→            prompt: 'Enter text to analyze for voice commands',
   260→            placeHolder: 'create a function called hello enter'
   261→        });
   262→
   263→        if (!input) {
   264→            return;
   265→        }
   266→
   267→        const parser = CommandParser.withSettings();
   268→        const tester = createCommandTester(parser);
   269→        const analysis = tester.analyze(input);
   270→
   271→        // First apply homophone normalization
   272→        const normalized = normalizeCommand(input);
   273→
   274→        let output = `Voice Command Analysis\n\n`;
   275→        output += `Original: "${input}"\n`;
   276→        output += `Normalized: "${normalized}"\n`;
   277→        output += `Cleaned text: "${analysis.cleaned}"\n`;
   278→        output += `Commands found: ${analysis.commandsFound}\n`;
   279→
   280→        if (analysis.commands.length > 0) {
   281→            output += '\nCommands:\n';
   282→            for (const cmd of analysis.commands) {
   283→                output += `  • ${cmd.action}`;
   284→                if (cmd.isTerminal) output += ' (terminal)';
   285→                if (cmd.params) output += ` ${JSON.stringify(cmd.params)}`;
   286→                output += '\n';
   287→            }
   288→        }
   289→
   290→        this.outputChannel.clear();
   291→        this.outputChannel.append(output);
   292→        this.outputChannel.show();
   293→    }
