   411→    /**
   412→     * Setup authentication (ADR-002)
   413→     */
   414→    private async setupAuthentication(): Promise<void> {
   415→        this.log('Starting authentication setup...');
   416→
   417→        // Step 1: Get backend URL
   418→        const backendUrl = await vscode.window.showInputBox({
   419→            prompt: 'Enter your VTThought backend URL',
   420→            value: this.state.backendUrl,
   421→            placeHolder: 'http://localhost:8000',
   422→            validateInput: (value) => {
   423→                if (!value || !value.startsWith('http')) {
   424→                    return 'Please enter a valid URL (http:// or https://)';
   425→                }
   426→                return null;
   427→            }
   428→        });
   429→
   430→        if (!backendUrl) {
   431→            this.log('Authentication setup cancelled: No backend URL provided');
   432→            return;
   433→        }
   434→
   435→        // Normalize URL (remove trailing slash)
   436→        const normalizedUrl = backendUrl.replace(/\/$/, '');
   437→        await this.tokenManager.storeBackendUrl(normalizedUrl);
   438→        this.state.backendUrl = normalizedUrl;
   439→
   440→        // Step 2: Test backend connection
   441→        this.log(`Testing connection to ${normalizedUrl}...`);
   442→        try {
   443→            const response = await fetch(`${normalizedUrl}/api/auth/mode`);
   444→            if (!response.ok) {
   445→                throw new Error(`HTTP ${response.status}`);
   446→            }
   447→
   448→            const authMode = await response.json() as { mode: string; single_user_mode: boolean };
   449→            this.log(`Backend auth mode: ${authMode.mode}`);
   450→
   451→            if (authMode.single_user_mode) {
   452→                // Single-user mode: no token needed
   453→                vscode.window.showInformationMessage(
   454→                    'VTThought: Backend configured in single-user mode. No token required.'
   455→                );
   456→                this.state.isAuthenticated = true;
   457→                this.updateStatusDisplay();
   458→                return;
   459→            }
   460→        } catch (error) {
   461→            const message = error instanceof Error ? error.message : String(error);
   462→            vscode.window.showErrorMessage(
   463→                `VTThought: Failed to connect to backend at ${normalizedUrl}. ${message}`
   464→            );
   465→            this.log(`Backend connection failed: ${message}`);
   466→            return;
   467→        }
   468→
   469→        // Step 3: Get token from user
   470→        const token = await vscode.window.showInputBox({
   471→            prompt: 'Enter your VTThought extension token (from backend settings)',
   472→            password: true,
   473→            placeHolder: 'vct_...',
   474→            validateInput: (value) => {
   475→                if (!value || !value.startsWith('vct_')) {
   476→                    return 'Please enter a valid token (starts with vct_)';
   477→                }
   478→                return null;
   479→            }
   480→        });
   481→
   482→        if (!token) {
   483→            this.log('Authentication setup cancelled: No token provided');
   484→            return;
   485→        }
   486→
   487→        // Store token
   488→        await this.tokenManager.storeToken(token);
   489→        this.state.isAuthenticated = true;
   490→
   491→        this.log('Authentication configured successfully');
   492→        vscode.window.showInformationMessage(
   493→            'VTThought: Authentication configured successfully!'
   494→        );
   495→        this.updateStatusDisplay();
   496→    }
